import {topics,definitions,simulate,makeTree} from './algorithms.mjs';
import {VoxelWorld} from './world.mjs';
const $=id=>document.getElementById(id);let saved;try{saved=JSON.parse(localStorage.getItem('blockcraft-journal')||'{}');}catch{saved={};}if(!saved||typeof saved!=='object')saved={};const progress={completed:Array.isArray(saved.completed)?saved.completed.filter(x=>definitions[x]):[],quizzes:Array.isArray(saved.quizzes)?saved.quizzes.filter(x=>definitions[x]):[]};
let currentTopic=topics[0],algorithm='bubble',values=[...currentTopic.values],target=6,frames=[],position=0,timer=null,filter='All worlds',sound=false,audio,toastTimer,tab='learn';const datasets=new Map();const cards=[];
const heroWorld=new VoxelWorld($('heroWorld'));heroWorld.set({topic:'sorting',terrain:'grass',hero:true,frame:{values:[3,6,4,9,5,7],active:[2,3],marked:[5],discarded:[]}});
const world=new VoxelWorld($('world'),{interactive:true,onInspect:hit=>toast(`Block ${hit.value} · ${currentTopic.id==='graph'?'node':'index'} ${currentTopic.id==='graph'?hit.value:hit.index}`)});
function persist(){try{localStorage.setItem('blockcraft-journal',JSON.stringify(progress));}catch{}updateProgress();}
function updateProgress(){$('xp').textContent=progress.completed.length*50+progress.quizzes.length*25;$('journalCount').textContent=progress.completed.length;for(const {topic,card} of cards){const count=topic.algorithms.filter(id=>progress.completed.includes(id)).length;card.querySelector('.card-status').textContent=count===topic.algorithms.length?'✓ EXPLORED':topic.level;card.querySelector('.card-bottom-label').textContent=count?`${count} / ${topic.algorithms.length} LESSONS COMPLETE`:`${topic.algorithms.length} ${topic.algorithms.length===1?'LESSON':'LESSONS'} · EXPLORE`;}$('completionBadge').textContent=progress.completed.includes(algorithm)?'✓ LESSON EXPLORED':'WORLD IN PROGRESS';}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function buildCards(){topics.forEach((topic,i)=>{const card=document.createElement('a');card.className='topic-card';card.href=`#world/${topic.id}`;card.style.setProperty('--card-color',topic.color);card.setAttribute('aria-label',`${topic.name}: ${topic.subject}`);card.innerHTML=`<div class="card-image"><canvas aria-hidden="true"></canvas><span class="card-number">0${i+1}</span><span class="card-status"></span></div><div class="card-body"><span class="card-subject">${topic.subject}</span><h3>${topic.name}</h3><p>${topic.description}</p><div class="card-bottom"><span class="card-bottom-label"></span><b>→</b></div></div>`;$('topicGrid').append(card);let frame={values:topic.id==='sorting'?[3,7,4,9,6]:[...topic.values],active:[],marked:[],discarded:[],nodes:[]};if(topic.id==='tree')frame.nodes=makeTree(topic.values);if(topic.id==='heap')frame=simulate('heap',topic.values).at(-1);if(topic.id==='hash')frame=simulate('hash',topic.values).at(-1);if(topic.id==='stack')frame.values=[4,7,2,9];const view=new VoxelWorld(card.querySelector('canvas'));view.set({topic:topic.id,terrain:topic.terrain,thumbnail:true,frame,algorithm:topic.algorithms[0]});cards.push({topic,card,view});});updateProgress();}
function applyFilter(){const q=$('topicSearch').value.trim().toLowerCase();let count=0;for(const {topic,card,view} of cards){const show=(filter==='All worlds'||topic.category===filter)&&`${topic.name} ${topic.subject} ${topic.tags.join(' ')}`.toLowerCase().includes(q);card.hidden=!show;if(show){count++;requestAnimationFrame(()=>view.draw());}}$('resultCount').textContent=`${count} ${count===1?'WORLD':'WORLDS'} TO EXPLORE`;$('empty').hidden=count!==0;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter);});}
function pause(){clearTimeout(timer);timer=null;$('play').textContent=position===frames.length-1?'↺ REPLAY':'▶ PLAY';$('play').setAttribute('aria-label',position===frames.length-1?'Replay animation':'Play animation');}
function prepare(){pause();frames=simulate(algorithm,values,target);position=0;$('timeline').max=frames.length-1;render();}
function complete(){if(position!==frames.length-1||progress.completed.includes(algorithm))return;progress.completed.push(algorithm);persist();toast('✦ Lesson explored! +50 XP. Try the practice quest next.');}
function soundBlock(){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.value=220+(position%7)*45;gain.gain.setValueAtTime(.04,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.08);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.09);}catch{sound=false;$('sound').setAttribute('aria-label','Enable sound');}}
function moveTo(n,award=true){position=Math.max(0,Math.min(frames.length-1,n));render();soundBlock();if(award)complete();}
function tick(){if(position>=frames.length-1){pause();return;}moveTo(position+1);if(position===frames.length-1){pause();return;}timer=setTimeout(tick,850/Number($('speed').value));}
function play(){if(timer){pause();return;}if(position===frames.length-1)moveTo(0,false);$('play').textContent='Ⅱ PAUSE';$('play').setAttribute('aria-label','Pause animation');timer=setTimeout(tick,100);}
function step(delta){pause();moveTo(position+delta);pause();}
function render(){const f=frames[position];if(!f)return;$('timeline').value=position;$('stepCount').textContent=`${position} / ${frames.length-1}`;$('back').disabled=position===0;$('step').disabled=position===frames.length-1;$('status').textContent=f.message;$('statusIcon').textContent=f.complete?'✓':'▸';$('comparisons').textContent=f.comparisons;$('comparisonLabel').textContent=['traverse','inorder','bfs','dfs'].includes(algorithm)?'NODES VISITED':'COMPARISONS';$('moves').textContent=f.moves;const def=definitions[algorithm];$('code').replaceChildren(...def.code.map((text,i)=>{const line=document.createElement('span');line.className=`code-line ${i===f.line?'highlight':''}`;const number=document.createElement('b');number.textContent=String(i+1).padStart(2,'0');line.append(number,document.createTextNode(text));return line;}));$('targetBadge').hidden=!def.target;$('targetBadge').querySelector('b').textContent=target;$('incomingBadge').hidden=f.incoming===undefined;if(f.incoming!==undefined)$('incomingBadge').textContent=`INCOMING: ${f.incoming}`;$('stateValues').replaceChildren(...f.values.map((value,i)=>chip(value,f.active.includes(i)?'active':f.discarded.includes(i)?'discarded':f.marked.includes(i)?'marked':'')));if(!f.values.length)$('stateValues').innerHTML='<span class="tray-empty">Empty storage</span>';$('trayLabel').textContent=algorithm==='hash'?'CHESTS':algorithm==='stack'?'STACK':algorithm==='queue'?'QUEUE':'VALUES';const isGraph=['bfs','dfs'].includes(algorithm);const auxiliary=isGraph?f.aux:f.output;$('auxTray').hidden=!isGraph&&!auxiliary.length;$('auxLabel').textContent=isGraph?algorithm==='bfs'?'QUEUE':'STACK':'OUTPUT';$('auxValues').replaceChildren(...auxiliary.map(v=>chip(v,'marked')));if(!auxiliary.length)$('auxValues').innerHTML='<span class="tray-empty">Empty</span>';world.set({topic:currentTopic.id,terrain:currentTopic.terrain,algorithm,frame:f});if(!timer)$('play').textContent=position===frames.length-1?'↺ REPLAY':'▶ PLAY';}
function chip(value,state=''){const s=document.createElement('span');s.className=`value-chip ${state}`;s.textContent=value===null?'·':value;return s;}
function setAlgorithm(id){algorithm=id;const def=definitions[id];$('algorithm').value=id;$('lessonTitle').textContent=def.name;$('description').textContent=def.intro;$('insight').textContent=def.insight;$('timeComplexity').textContent=def.time;$('spaceComplexity').textContent=def.space;prepare();renderPractice();updateProgress();}
function openWorld(id){const next=topics.find(t=>t.id===id)||topics[0];pause();currentTopic=next;values=[...(datasets.get(id)||next.values)];target=next.id==='tree'?10:6;$('library').hidden=true;$('lab').hidden=false;$('libraryLink').classList.remove('active');$('biomeName').textContent=next.name.toUpperCase();$('labTitle').textContent=next.name;$('labCategory').textContent=next.category.toUpperCase();$('sceneCaption').textContent=`${next.name.toUpperCase()} // ${String(topics.indexOf(next)+1).padStart(2,'0')}`;$('algorithm').replaceChildren(...next.algorithms.map(id=>{const option=document.createElement('option');option.value=id;option.textContent=definitions[id].name;return option;}));$('edit').hidden=id==='graph';$('shuffle').hidden=id==='graph';world.reset();setAlgorithm(next.algorithms[0]);switchTab('learn');window.scrollTo(0,0);}
function route(){const match=location.hash.match(/^#world\/([a-z]+)$/);if(match){openWorld(match[1]);}else{pause();$('lab').hidden=true;$('library').hidden=false;$('libraryLink').classList.add('active');applyFilter();requestAnimationFrame(()=>heroWorld.draw());}}
function switchTab(name){tab=name;$('learnPanel').hidden=name!=='learn';$('practicePanel').hidden=name!=='practice';document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===name));}
function renderPractice(){const def=definitions[algorithm];$('question').textContent=def.question;$('answerFeedback').textContent=progress.quizzes.includes(algorithm)?'✓ Quest completed. You can practice again anytime.':'';$('answers').replaceChildren(...def.answers.map((text,i)=>{const button=document.createElement('button');button.className='answer';button.innerHTML=`<span>${String.fromCharCode(65+i)}</span>`;button.append(document.createTextNode(text));button.onclick=()=>{const correct=i===def.correct;button.classList.toggle('correct',correct);button.classList.toggle('incorrect',!correct);$('answerFeedback').textContent=correct?`Correct! ${def.reason}`:'Not quite. Revisit the lesson, or try another answer.';if(correct){[...$('answers').children].forEach(b=>b.disabled=true);if(!progress.quizzes.includes(algorithm)){progress.quizzes.push(algorithm);persist();toast('✦ Quest complete! +25 XP.');}}};return button;}));}
function randomValues(){const n=currentTopic.id==='list'?5:currentTopic.id==='tree'||currentTopic.id==='heap'?7:8;return Array.from({length:n},()=>1+Math.floor(Math.random()* (currentTopic.id==='sorting'?12:20)));}
function editData(){$('dataInput').value=values.join(', ');$('targetInput').value=target;$('targetLabel').hidden=!definitions[algorithm].target;$('error').textContent='';const max=currentTopic.id==='sorting'||currentTopic.id==='stack'?20:99;$('inputHelp').textContent=`Enter 3–10 whole numbers from 1 to ${max}, separated by commas.`;$('dataNote').textContent=algorithm==='binary'?'Binary search sorts your input automatically before searching.':currentTopic.id==='tree'?'Values are inserted in this order. Duplicate values are omitted.':algorithm==='hash'?'Chest address = value mod 11. Up to 10 items keep at least one chest empty.':'';$('dataDialog').showModal();}
function applyData(){const pieces=$('dataInput').value.split(',').map(x=>x.trim()),a=pieces.map(Number),t=Number($('targetInput').value);const max=currentTopic.id==='sorting'||currentTopic.id==='stack'?20:99;if(pieces.some(p=>!p)||a.length<3||a.length>10||a.some(v=>!Number.isInteger(v)||v<1||v>max)){$('error').textContent=`Use 3–10 whole numbers between 1 and ${max}, separated by commas.`;return;}if(definitions[algorithm].target&&(!Number.isInteger(t)||t<1||t>99)){$('error').textContent='Choose a whole-number target between 1 and 99.';return;}values=a;target=t;datasets.set(currentTopic.id,[...values]);prepare();$('dataDialog').close();}
function showJournal(){$('journalEntries').replaceChildren();if(!progress.completed.length&&!progress.quizzes.length){$('journalEntries').innerHTML='<p>Your journal is waiting for its first adventure. Finish an animation or solve a practice quest to earn XP.</p>';}else{for(const topic of topics)for(const id of topic.algorithms){if(!progress.completed.includes(id)&&!progress.quizzes.includes(id))continue;const row=document.createElement('a');row.className='journal-entry';row.href=`#world/${topic.id}`;row.innerHTML=`<div><strong>${definitions[id].name}</strong><small>${topic.name}</small></div><span>${progress.completed.includes(id)?'✓ EXPLORED':''}${progress.quizzes.includes(id)?' ✦ QUEST':''}</span>`;row.onclick=()=>{$('journalDialog').close();if(location.hash===`#world/${topic.id}`)openWorld(topic.id);setTimeout(()=>setAlgorithm(id),0);};$('journalEntries').append(row);}}$('journalDialog').showModal();}
$('start').onclick=()=>location.hash='world/sorting';$('topicSearch').oninput=applyFilter;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;applyFilter();});$('algorithm').onchange=e=>setAlgorithm(e.target.value);$('play').onclick=play;$('step').onclick=()=>step(1);$('back').onclick=()=>step(-1);$('reset').onclick=()=>{pause();moveTo(0,false);pause();};$('timeline').oninput=e=>{pause();moveTo(Number(e.target.value));pause();};$('speed').onchange=()=>{if(timer){clearTimeout(timer);timer=setTimeout(tick,850/Number($('speed').value));}};$('shuffle').onclick=()=>{values=randomValues();datasets.set(currentTopic.id,[...values]);prepare();};$('edit').onclick=editData;$('cancel').onclick=()=>$('dataDialog').close();$('apply').onclick=applyData;document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{let a=b.dataset.preset==='duplicates'?[5,3,5,2,3,8]:randomValues();if(b.dataset.preset==='sorted')a.sort((a,b)=>a-b);if(b.dataset.preset==='reversed')a.sort((a,b)=>b-a);$('dataInput').value=a.join(', ');});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('returnLesson').onclick=()=>switchTab('learn');$('practiceNav').onclick=()=>{if($('lab').hidden){location.hash='world/sorting';setTimeout(()=>switchTab('practice'),0);}else switchTab('practice');};$('journalNav').onclick=showJournal;$('closeJournal').onclick=()=>$('journalDialog').close();$('resetCamera').onclick=()=>world.reset();$('dayNight').onclick=()=>{world.night=!world.night;$('dayNight').textContent=world.night?'☀':'☾';$('dayNight').setAttribute('aria-label',world.night?'Switch to day':'Switch to night');world.draw();};$('sound').onclick=()=>{sound=!sound;$('sound').style.color=sound?'#b8ed80':'';$('sound').setAttribute('aria-label',sound?'Disable sound':'Enable sound');soundBlock();toast(sound?'Block sounds on':'Block sounds off');};document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='/'&&!$('library').hidden){e.preventDefault();$('topicSearch').focus();return;}if($('lab').hidden||document.activeElement.tagName==='BUTTON')return;if(e.code==='Space'){e.preventDefault();play();}if(e.key==='ArrowRight'){e.preventDefault();step(1);}if(e.key==='ArrowLeft'){e.preventDefault();step(-1);}});window.addEventListener('hashchange',route);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});buildCards();route();
